      console.log("Disponible hasta 120:", 120 - minutos);
      console.log("Alcanza 30:", 30 <= minutos);
      console.log("Igual a referencia:", referencia === minutos);
      console.log("Distinto de referencia:", referencia !== minutos);
      console.log("Recomendación:", recomendacion);
      console.log("Sesiones programadas:", dias);
